def compress(text):
    """Return text with runs of a letter replaced by the letter and the run length."""
    parts = []
    start = 0
    for i in range(1, len(text) + 1):
        if i == len(text) or text[i] != text[start]:
            parts.append(text[start] + str(i - start))
            start = i
    compressed = ''.join(parts)
    return compressed if len(compressed) < len(text) else text

