class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next


def reverse(head):
    """Reverse the list starting at head in place and return the new head."""
    previous = None
    while head is not None:
        head.next, previous, head = previous, head, head.next
    return previous

