def first_unique(text):
    """Return the index of the first character that appears once in text, or -1."""
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    for i, char in enumerate(text):
        if counts[char] == 1:
            return i
    return -1

