problems.reference_solution:
class MinStack:
    def __init__(self):
        # Each entry keeps the minimum of itself and everything below it.
        self.entries = []

    def push(self, value):
        low = min(value, self.entries[-1][1]) if self.entries else value
        self.entries.append((value, low))

    def pop(self):
        return self.entries.pop()[0]

    def top(self):
        return self.entries[-1][0]

    def get_min(self):
        return self.entries[-1][1]

