problems.reference_solution:
class TreeNode:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right


def is_search_tree(root, low=None, high=None):
    """Return True when the tree under root is a binary search tree."""
    if root is None:
        return True
    if (low is not None and root.value <= low) or (high is not None and root.value >= high):
        return False
    return is_search_tree(root.left, low, root.value) and is_search_tree(
        root.right, root.value, high
    )

problems.tests:
from solution import *

T = TreeNode


def _balanced(values):
    if not values:
        return None
    middle = len(values) // 2
    return T(values[middle], _balanced(values[:middle]), _balanced(values[middle + 1 :]))


def test_example_1():
    """A root with a smaller left and a larger right child."""
    assert is_search_tree(T(2, T(1), T(3))) is True


def test_example_2():
    """A grandchild on the wrong side of the root."""
    assert is_search_tree(T(5, T(1), T(6, T(4), T(7)))) is False


def test_empty_tree():
    """An empty tree is a search tree."""
    assert is_search_tree(None) is True


def test_single_node():
    """One node is a search tree."""
    assert is_search_tree(T(0)) is True


def test_child_on_wrong_side():
    """A left child larger than its parent."""
    assert is_search_tree(T(2, T(3))) is False


def test_deep_violation_on_the_left():
    """A value deep in the left subtree is larger than the root."""
    assert is_search_tree(T(10, T(5, None, T(8, None, T(12))), T(15))) is False


def test_repeated_value():
    """Equal values are not allowed on either side."""
    assert is_search_tree(T(2, T(2))) is False
    assert is_search_tree(T(2, None, T(2))) is False


def test_large_tree():
    """A balanced tree of 50,000 nodes, valid and then with one value out of place."""
    values = list(range(0, 100000, 2))
    root = _balanced(values)
    assert is_search_tree(root) is True
    node = root
    while node.right.right is not None:
        node = node.right
    node.right.value = values[len(values) // 2] - 1
    assert is_search_tree(root) is False

